from collections.abc import MutableMapping
import math
import threading
import time

def check_rate_limit(buckets: MutableMapping[str, dict[str, float]], key: str, capacity: float=10.0, refill_rate: float=1.0, cost: float=1.0, now: float | None=None) -> tuple[bool, float]:
    if capacity <= 0 or refill_rate <= 0 or cost <= 0:
        raise ValueError('capacity, refill_rate and cost must be positive')
    if cost > capacity:
        raise ValueError('cost can never be satisfied: it exceeds capacity')
    now = time.monotonic() if now is None else now
    bucket = buckets.get(key)
    if bucket is None:
        bucket = buckets[key] = {'tokens': float(capacity), 'last': now}
    elapsed = max(0.0, now - bucket['last'])
    bucket['tokens'] = min(float(capacity), bucket['tokens'] + elapsed * refill_rate)
    bucket['last'] = now
    if bucket['tokens'] >= cost:
        bucket['tokens'] -= cost
        return (True, 0.0)
    return (False, (cost - bucket['tokens']) / refill_rate)

_BUCKETS: dict[str, dict[str, float]] = {}
_LOCK = threading.Lock()

def get_client_key(headers: MutableMapping[str, str], remote_addr: str) -> str:
    api_key = headers.get('X-API-Key')
    if api_key:
        return 'key:' + api_key
    return 'ip:' + remote_addr

def rate_limit_request(headers: MutableMapping[str, str], remote_addr: str, limit_per_minute: int=60) -> tuple[int, dict[str, str]]:
    """Call at the start of each request handler / middleware.

    Returns (200, {}) if the request may proceed, otherwise
    (429, {'Retry-After': '<seconds>'}) which you should send back as the response.
    """
    key = get_client_key(headers, remote_addr)
    with _LOCK:
        allowed, retry_after = check_rate_limit(
            _BUCKETS, key,
            capacity=limit_per_minute,
            refill_rate=limit_per_minute / 60.0,
        )
    if allowed:
        return 200, {}
    return 429, {'Retry-After': str(max(1, math.ceil(retry_after)))}

